//! What an event does to an import proposal, decided by the machine the proposal's document
//! generates (`machines/import_life/import_life.scxml`, regenerated by `machines/generate.sh`).
//!
//! `proposals.rs` keeps the record: what the proposal is made of, its questions, its decisions and
//! the moments. This module is the seam to the rules, as `request_life` is for a generation request
//! (ADR 0016, 0037). A proposal stands where its state says it does; [`decide`] stands a machine
//! there, hands it one event, and reads back whether the event was taken, why it was not, and the
//! state that results. No rule is written here, and none in `proposals.rs`: which events a state
//! takes, and what accepting is refused for, are the document's.
//!
//! The machine is stood where a proposal stands by taking the saved state the engine writes of a
//! fresh one and replacing the parts a proposal keeps (where it is). The rest of that text is the
//! engine's own, so this module names no more of the saved-state format than it has to.

use std::sync::OnceLock;

use sce_rust_runtime::saved_state::SavedState;
use sce_rust_runtime::Engine;
use serde_json::{json, Value};

use crate::proposals::ProposalState;

#[path = "generated/import_life_sm.rs"]
mod machine;

use machine::{ImportLifePersist, ImportLifePolicy};

/// One thing said to a proposal. What each carries is what a rule reads and nothing more.
#[derive(Debug, Clone, Copy)]
pub(crate) enum Event {
    /// The owner accepts it. `head_matches`: the spec's text head is still the revision the proposal
    /// was made against. `undecided`: how many of the questions it asked have no decision.
    Accept { head_matches: bool, undecided: u32 },
    /// The owner decides about a block. What was decided is a line of the log and no rule reads it;
    /// the proposal's life is asked only whether a decision may be taken.
    Decide,
    /// The owner declines it.
    Reject,
    /// It is replaced, or the original it was made of was.
    Supersede,
}

impl Event {
    /// The event as the machine is told it: its name and its payload, as JSON.
    fn wire(&self) -> (&'static str, String) {
        match *self {
            Event::Accept {
                head_matches,
                undecided,
            } => (
                "accept",
                json!({ "headMatches": head_matches, "undecided": undecided }).to_string(),
            ),
            Event::Decide => ("decide", String::new()),
            Event::Reject => ("reject", String::new()),
            Event::Supersede => ("supersede", String::new()),
        }
    }
}

/// What the machine said of an event.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum Verdict {
    /// The event was taken.
    Ok,
    /// The spec's text is not the one the proposal was made against.
    Moved,
    /// A question the proposal asked has no decision.
    Undecided,
    /// The proposal ended and takes no other word.
    Ended,
    /// There was nothing for the event to do.
    Nothing,
}

/// What the machine holds after an event.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct Answer {
    pub verdict: Verdict,
    pub state: ProposalState,
}

const STATES: [ProposalState; 4] = [
    ProposalState::Pending,
    ProposalState::Accepted,
    ProposalState::Rejected,
    ProposalState::Superseded,
];

/// The states a machine is in at once when it is in `state`: the document's root, the group the
/// state belongs to (a pending proposal is a state of its own), and the state.
fn configuration(state: ProposalState) -> Vec<&'static str> {
    if state.is_open() {
        vec!["proposal", "pending"]
    } else {
        vec!["proposal", "ended", state.word()]
    }
}

/// The saved state of a machine nothing has happened to, written by the engine.
fn fresh() -> &'static Value {
    static FRESH: OnceLock<Value> = OnceLock::new();
    FRESH.get_or_init(|| {
        let mut engine = Engine::new(ImportLifePolicy::new());
        engine.initialize();
        let text = engine
            .save()
            .expect("a machine that was just started can be saved")
            .to_json();
        serde_json::from_str(&text).expect("a saved state is JSON")
    })
}

/// A machine standing where a proposal in `state` stands.
fn stand(state: ProposalState) -> Engine<ImportLifePolicy> {
    let mut saved = fresh().clone();
    saved["configuration"] = json!(configuration(state));
    saved["current"] = json!(state.word());
    saved["variables"]["verdict"] = json!("unanswered");

    let saved = SavedState::from_json(&saved.to_string()).unwrap_or_else(|why| {
        panic!(
            "the import machine cannot stand in {state:?}: {}",
            why.reason()
        )
    });
    Engine::<ImportLifePolicy>::restore(ImportLifePolicy::new(), &saved).unwrap_or_else(|why| {
        panic!(
            "the import machine cannot stand in {state:?}: {}",
            why.reason()
        )
    })
}

/// Stand a machine where a proposal in `state` stands, say `event` to it, and read what it holds.
pub(crate) fn decide(state: ProposalState, event: &Event) -> Answer {
    let mut engine = stand(state);
    let (name, data) = event.wire();
    engine.raise_external_by_name(name, &data);
    engine.step();
    let text = engine
        .save()
        .unwrap_or_else(|why| panic!("the import machine cannot be saved: {}", why.reason()))
        .to_json();
    let after: Value = serde_json::from_str(&text).expect("a saved state is JSON");

    let word = |value: &Value| value.as_str().unwrap_or_default().to_string();
    let verdict = match word(&after["variables"]["verdict"]).as_str() {
        "ok" => Verdict::Ok,
        "moved" => Verdict::Moved,
        "undecided" => Verdict::Undecided,
        "ended" => Verdict::Ended,
        "nothing" => Verdict::Nothing,
        _ => panic!("the import machine took no `{name}` event from {state:?}"),
    };
    let current = word(&after["current"]);
    let state = STATES
        .into_iter()
        .find(|state| state.word() == current)
        .unwrap_or_else(|| panic!("the import machine stands in `{current}`, which is no state"));
    Answer { verdict, state }
}

#[cfg(test)]
mod tests {
    use super::*;
    use ProposalState::{Accepted, Pending, Rejected, Superseded};

    fn accept(head_matches: bool, undecided: u32) -> Event {
        Event::Accept {
            head_matches,
            undecided,
        }
    }

    fn says(state: ProposalState, event: Event) -> (Verdict, ProposalState) {
        let answer = decide(state, &event);
        (answer.verdict, answer.state)
    }

    #[test]
    fn a_pending_proposal_whose_head_is_there_and_whose_questions_are_answered_is_accepted() {
        assert_eq!(says(Pending, accept(true, 0)), (Verdict::Ok, Accepted));
    }

    #[test]
    fn accepting_is_refused_for_a_moved_head_before_it_is_refused_for_an_open_question() {
        // The rule that decides which is said first: a spec that moved is looked at again whatever
        // was decided, and the question still open is answered against the text there is now.
        assert_eq!(says(Pending, accept(false, 0)), (Verdict::Moved, Pending));
        assert_eq!(says(Pending, accept(false, 3)), (Verdict::Moved, Pending));
    }

    #[test]
    fn accepting_is_refused_while_a_question_has_no_decision_and_one_is_enough() {
        for open in [1, 2, 1000] {
            assert_eq!(
                says(Pending, accept(true, open)),
                (Verdict::Undecided, Pending),
                "{open}"
            );
        }
    }

    #[test]
    fn a_refusal_leaves_the_proposal_pending_so_that_nothing_is_lost() {
        for event in [accept(false, 0), accept(true, 2)] {
            assert_eq!(says(Pending, event).1, Pending);
        }
    }

    #[test]
    fn the_same_accept_again_is_the_same_acceptance_whatever_has_happened_to_the_spec_since() {
        // The spec moved once the proposal was accepted: it is the head the accept itself made.
        for (head_matches, undecided) in [(true, 0), (false, 0), (false, 4), (true, 4)] {
            assert_eq!(
                says(Accepted, accept(head_matches, undecided)),
                (Verdict::Ok, Accepted)
            );
        }
    }

    #[test]
    fn what_ended_otherwise_takes_no_accept() {
        for state in [Rejected, Superseded] {
            assert_eq!(says(state, accept(true, 0)), (Verdict::Ended, state));
        }
    }

    #[test]
    fn rejecting_is_taken_by_a_pending_proposal_and_is_the_same_word_when_said_again() {
        assert_eq!(says(Pending, Event::Reject), (Verdict::Ok, Rejected));
        assert_eq!(says(Rejected, Event::Reject), (Verdict::Ok, Rejected));
    }

    #[test]
    fn what_was_accepted_or_superseded_is_not_rejected_afterwards() {
        for state in [Accepted, Superseded] {
            assert_eq!(says(state, Event::Reject), (Verdict::Ended, state));
        }
    }

    #[test]
    fn superseding_is_taken_by_a_pending_proposal_and_is_nothing_to_one_that_ended() {
        assert_eq!(says(Pending, Event::Supersede), (Verdict::Ok, Superseded));
        for state in [Accepted, Rejected, Superseded] {
            assert_eq!(says(state, Event::Supersede), (Verdict::Nothing, state));
        }
    }

    #[test]
    fn a_decision_is_taken_while_the_proposal_is_open_and_changes_nothing_of_its_life() {
        assert_eq!(says(Pending, Event::Decide), (Verdict::Ok, Pending));
    }

    #[test]
    fn nothing_is_decided_about_what_ended() {
        for state in [Accepted, Rejected, Superseded] {
            assert_eq!(says(state, Event::Decide), (Verdict::Ended, state));
        }
    }

    #[test]
    fn every_state_and_every_event_is_answered() {
        // A pair the document has no transition for would panic with `took no event`.
        for state in STATES {
            for event in [
                accept(true, 0),
                accept(false, 1),
                Event::Decide,
                Event::Reject,
                Event::Supersede,
            ] {
                let _ = decide(state, &event);
            }
        }
    }
}
